#ifndef TICKET_OPERATIONS_SCHEMA_H
#define TICKET_OPERATIONS_SCHEMA_H
#define OPERATIONS_SCHEMA_SQL_CONFIG \
"CREATE TABLE IF NOT EXISTS operations_rules(id INTEGER PRIMARY KEY,name TEXT NOT NULL,mailbox_id INTEGER REFERENCES raw_mailboxes(id),sender_email TEXT NOT NULL DEFAULT '',contains_text TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',group_name TEXT NOT NULL DEFAULT '',job_id INTEGER,job_code TEXT,job_name TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 100,revision INTEGER NOT NULL DEFAULT 1);" \
"CREATE TABLE IF NOT EXISTS sla_policies(id INTEGER PRIMARY KEY,name TEXT NOT NULL,job_id INTEGER,priority TEXT NOT NULL DEFAULT 'all',response_minutes INTEGER NOT NULL,resolution_minutes INTEGER NOT NULL,timezone TEXT NOT NULL,weekdays INTEGER NOT NULL,day_start INTEGER NOT NULL,day_end INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1);" \
"INSERT INTO sla_policies(name,priority,response_minutes,resolution_minutes,timezone,weekdays,day_start,day_end) SELECT 'Standard bassa','low',480,2400,'Europe/Rome',62,540,1080 WHERE NOT EXISTS(SELECT 1 FROM sla_policies);" \
"INSERT INTO sla_policies(name,priority,response_minutes,resolution_minutes,timezone,weekdays,day_start,day_end) SELECT 'Standard normale','normal',240,960,'Europe/Rome',62,540,1080 WHERE NOT EXISTS(SELECT 1 FROM sla_policies WHERE priority='normal' AND job_id IS NULL);" \
"INSERT INTO sla_policies(name,priority,response_minutes,resolution_minutes,timezone,weekdays,day_start,day_end) SELECT 'Standard alta','high',60,480,'Europe/Rome',62,540,1080 WHERE NOT EXISTS(SELECT 1 FROM sla_policies WHERE priority='high' AND job_id IS NULL);" \
"INSERT INTO sla_policies(name,priority,response_minutes,resolution_minutes,timezone,weekdays,day_start,day_end) SELECT 'Standard urgente','urgent',15,240,'Europe/Rome',62,540,1080 WHERE NOT EXISTS(SELECT 1 FROM sla_policies WHERE priority='urgent' AND job_id IS NULL);"
#define OPERATIONS_SCHEMA_SQL_STATE \
"CREATE TABLE IF NOT EXISTS ticket_operations(ticket_id INTEGER PRIMARY KEY REFERENCES tickets(id),impact TEXT NOT NULL DEFAULT 'medium',urgency TEXT NOT NULL DEFAULT 'medium',assessed INTEGER NOT NULL DEFAULT 0,category TEXT NOT NULL DEFAULT '',group_name TEXT NOT NULL DEFAULT '',override_reason TEXT NOT NULL DEFAULT '',waiting_reason TEXT,follow_up_at INTEGER,first_response_at INTEGER,resolved_at INTEGER,reopened_count INTEGER NOT NULL DEFAULT 0,policy_id INTEGER,policy_name TEXT NOT NULL DEFAULT '',sla_timezone TEXT NOT NULL DEFAULT 'Europe/Rome',sla_weekdays INTEGER NOT NULL DEFAULT 62,sla_day_start INTEGER NOT NULL DEFAULT 540,sla_day_end INTEGER NOT NULL DEFAULT 1080,response_budget INTEGER NOT NULL DEFAULT 240,resolution_budget INTEGER NOT NULL DEFAULT 960,started_at INTEGER NOT NULL);" \
"CREATE TABLE IF NOT EXISTS ticket_wait_intervals(id INTEGER PRIMARY KEY,ticket_id INTEGER NOT NULL REFERENCES tickets(id),started_at INTEGER NOT NULL,ended_at INTEGER);" \
"CREATE INDEX IF NOT EXISTS ticket_wait_ticket_idx ON ticket_wait_intervals(ticket_id,id);" \
"CREATE TABLE IF NOT EXISTS operations_views(id INTEGER PRIMARY KEY,name TEXT NOT NULL,filters TEXT NOT NULL,view TEXT NOT NULL,owner_id INTEGER NOT NULL REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1);" \
"CREATE TABLE IF NOT EXISTS ticket_drafts(ticket_id INTEGER NOT NULL REFERENCES tickets(id),user_id INTEGER NOT NULL REFERENCES users(id),revision INTEGER NOT NULL,base_revision INTEGER NOT NULL,body TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(ticket_id,user_id));" \
"INSERT OR IGNORE INTO ticket_operations(ticket_id,impact,urgency,resolved_at,policy_name,response_budget,resolution_budget,started_at) SELECT id,CASE WHEN priority='low' THEN 'low' WHEN priority='normal' THEN 'medium' ELSE 'high' END,CASE WHEN priority='low' THEN 'low' WHEN priority='urgent' THEN 'high' ELSE 'medium' END,CASE WHEN status IN('resolved','closed') THEN CAST(strftime('%s',updated_at) AS INTEGER) ELSE NULL END,'Standard',CASE priority WHEN 'low' THEN 480 WHEN 'high' THEN 60 WHEN 'urgent' THEN 15 ELSE 240 END,CASE priority WHEN 'low' THEN 2400 WHEN 'high' THEN 480 WHEN 'urgent' THEN 240 ELSE 960 END,CAST(strftime('%s',created_at) AS INTEGER) FROM tickets;" \
"CREATE TEMP TABLE ticket_presence(ticket_id INTEGER NOT NULL,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL,editing INTEGER NOT NULL,last_seen INTEGER NOT NULL,PRIMARY KEY(ticket_id,token_hash));" \
"CREATE TEMP TABLE bulk_previews(token TEXT PRIMARY KEY,token_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,body TEXT NOT NULL,result TEXT);" \
"CREATE TEMP TABLE operations_filter_tickets(id INTEGER PRIMARY KEY);" \
"CREATE TEMP TRIGGER operations_session_delete AFTER DELETE ON sessions BEGIN DELETE FROM ticket_presence WHERE token_hash=OLD.token_hash; DELETE FROM bulk_previews WHERE token_hash=OLD.token_hash; END;"
#endif
